WITH flagged AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY device ORDER BY started_at ASC, id ASC) > INTERVAL '14' DAY THEN 1 ELSE 0 END AS session_start_flag FROM sessions) SELECT id, customer_id, device, started_at, SUM(session_start_flag) OVER (PARTITION BY device ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged;
